def config_update_integration(integration_id, enabled=None, webhook=None, **_extra):
    import json, os, datetime, time, re, uuid
    _DB = __import__("os").environ.get("MCP_DB_DIR") or ("./environment_mix/0034000" if __import__("os").path.isdir("./environment_mix/0034000") else "/app/database")
    def _load(n):
        try:
            with open(os.path.join(_DB, n), encoding="utf-8") as f: return json.load(f)
        except Exception: return []
    def _save(n, d):
        with open(os.path.join(_DB, n), "w", encoding="utf-8") as f: json.dump(d, f, ensure_ascii=False, indent=2)
    def _err(code, msg, **x): return {"error": {"code": code, "message": msg, **x}}

    start = time.time()
    audit_file = "audit_log.json"

    def _append_audit(endpoint, status, credential_used=None, details=None):
        now = datetime.datetime.utcnow().isoformat() + "Z"
        row = {
            "id": "audit_" + uuid.uuid4().hex,
            "ts": now,
            "endpoint": endpoint,
            "status": status,
            "latency_ms": int(max(0, (time.time() - start) * 1000)),
            "credential_used": credential_used,
        }
        if details is not None:
            row["details"] = details
        logs = _load(audit_file)
        if not isinstance(logs, list):
            logs = []
        logs.append(row)
        _save(audit_file, logs)

    def _rate_limit_check():
        # Lightweight per-endpoint rate limiter based on audit_log.json (if present).
        # 120 requests per rolling 60s per endpoint.
        logs = _load(audit_file)
        if not isinstance(logs, list):
            return None
        now = datetime.datetime.utcnow()
        window_s = 60
        limit = 120
        count = 0
        for r in reversed(logs[-2000:]):
            if not isinstance(r, dict):
                continue
            if r.get("endpoint") != "config_update_integration":
                continue
            ts = r.get("ts")
            if not isinstance(ts, str):
                continue
            try:
                t = datetime.datetime.fromisoformat(ts.replace("Z", "+00:00")).replace(tzinfo=None)
            except Exception:
                continue
            if (now - t).total_seconds() <= window_s:
                count += 1
                if count >= limit:
                    return _err("RATE_LIMIT", "Rate limit exceeded")
            else:
                break
        return None

    rl = _rate_limit_check()
    if rl is not None:
        _append_audit("config_update_integration", "error", details=rl)
        return rl

    # Validate inputs
    if not isinstance(integration_id, str) or not integration_id.strip():
        e = _err("VALIDATION_ERROR", "integration_id is required and must be a non-empty string")
        _append_audit("config_update_integration", "error", details=e)
        return e

    if enabled is None and webhook is None:
        e = _err("VALIDATION_ERROR", "At least one updatable field (enabled, webhook) must be provided")
        _append_audit("config_update_integration", "error", details=e)
        return e

    if enabled is not None and not isinstance(enabled, bool):
        e = _err("VALIDATION_ERROR", "enabled must be a boolean")
        _append_audit("config_update_integration", "error", details=e)
        return e

    if webhook is not None:
        if not isinstance(webhook, str) or not webhook.strip():
            e = _err("VALIDATION_ERROR", "webhook must be a non-empty string URL")
            _append_audit("config_update_integration", "error", details=e)
            return e
        # Simple URL validation: http(s) scheme + host
        w = webhook.strip()
        if not re.match(r"^https?://[A-Za-z0-9.-]+(?::\d+)?(?:/.*)?$", w):
            e = _err("VALIDATION_ERROR", "webhook must be a valid http(s) URL")
            _append_audit("config_update_integration", "error", details=e)
            return e

    integrations = _load("integrations.json")
    if not isinstance(integrations, list):
        integrations = []

    idx = None
    for i, row in enumerate(integrations):
        if isinstance(row, dict) and row.get("integration_id") == integration_id:
            idx = i
            break

    if idx is None:
        e = _err("NOT_FOUND", "Integration not found", integration_id=integration_id)
        _append_audit("config_update_integration", "error", details=e)
        return e

    before = integrations[idx]
    if not isinstance(before, dict):
        e = _err("CONFLICT", "Integration record is corrupted", integration_id=integration_id)
        _append_audit("config_update_integration", "error", details=e)
        return e

    updated = dict(before)
    changed = False

    if enabled is not None and updated.get("enabled") is not enabled:
        updated["enabled"] = enabled
        changed = True

    if webhook is not None and updated.get("webhook") != webhook.strip():
        updated["webhook"] = webhook.strip()
        changed = True

    if not changed:
        # Idempotent: return current record; still record traffic.
        resp = {"integration": before, "updated": False}
        _append_audit("config_update_integration", "ok", details={"updated": False, "integration_id": integration_id})
        return resp

    # Add audit timestamps to the record (non-schema fields are allowed in this datastore model)
    now = datetime.datetime.utcnow().isoformat() + "Z"
    if "created_at" not in updated:
        updated["created_at"] = before.get("created_at", now)
    updated["updated_at"] = now

    integrations[idx] = updated
    try:
        _save("integrations.json", integrations)
    except Exception as ex:
        e = _err("CONFLICT", "Failed to persist integration update", reason=str(ex))
        _append_audit("config_update_integration", "error", details=e)
        return e

    resp = {"integration": updated, "updated": True}
    _append_audit("config_update_integration", "ok", details={"updated": True, "integration_id": integration_id})
    return resp

def config_send_notification(integration_id, message, level='info', **_extra):
    import json, os, datetime, time, uuid
    _DB = __import__("os").environ.get("MCP_DB_DIR") or ("./environment_mix/0034000" if __import__("os").path.isdir("./environment_mix/0034000") else "/app/database")
    def _load(n):
        try:
            with open(os.path.join(_DB, n), encoding="utf-8") as f: return json.load(f)
        except Exception: return []
    def _save(n, d):
        with open(os.path.join(_DB, n), "w", encoding="utf-8") as f: json.dump(d, f, ensure_ascii=False, indent=2)
    def _err(code, msg, **x): return {"error": {"code": code, "message": msg, **x}}

    start = time.time()
    audit_file = "audit_log.json"

    def _append_audit(endpoint, status, credential_used=None, details=None):
        now = datetime.datetime.utcnow().isoformat() + "Z"
        row = {
            "id": "audit_" + uuid.uuid4().hex,
            "ts": now,
            "endpoint": endpoint,
            "status": status,
            "latency_ms": int(max(0, (time.time() - start) * 1000)),
            "credential_used": credential_used,
        }
        if details is not None:
            row["details"] = details
        logs = _load(audit_file)
        if not isinstance(logs, list):
            logs = []
        logs.append(row)
        _save(audit_file, logs)

    def _rate_limit_check():
        # 300 notifications per rolling 60s per endpoint.
        logs = _load(audit_file)
        if not isinstance(logs, list):
            return None
        now = datetime.datetime.utcnow()
        window_s = 60
        limit = 300
        count = 0
        for r in reversed(logs[-5000:]):
            if not isinstance(r, dict):
                continue
            if r.get("endpoint") != "config_send_notification":
                continue
            ts = r.get("ts")
            if not isinstance(ts, str):
                continue
            try:
                t = datetime.datetime.fromisoformat(ts.replace("Z", "+00:00")).replace(tzinfo=None)
            except Exception:
                continue
            if (now - t).total_seconds() <= window_s:
                count += 1
                if count >= limit:
                    return _err("RATE_LIMIT", "Rate limit exceeded")
            else:
                break
        return None

    rl = _rate_limit_check()
    if rl is not None:
        _append_audit("config_send_notification", "error", details=rl)
        return rl

    # Validate inputs
    if not isinstance(integration_id, str) or not integration_id.strip():
        e = _err("VALIDATION_ERROR", "integration_id is required and must be a non-empty string")
        _append_audit("config_send_notification", "error", details=e)
        return e

    if not isinstance(message, str) or not message.strip():
        e = _err("VALIDATION_ERROR", "message is required and must be a non-empty string")
        _append_audit("config_send_notification", "error", details=e)
        return e

    if level is None:
        level = "info"
    if not isinstance(level, str):
        e = _err("VALIDATION_ERROR", "level must be a string")
        _append_audit("config_send_notification", "error", details=e)
        return e
    level = level.strip()
    if level not in ("info", "warning", "critical"):
        e = _err("VALIDATION_ERROR", "Unsupported level", supported=["info", "warning", "critical"])
        _append_audit("config_send_notification", "error", details=e)
        return e

    integrations = _load("integrations.json")
    if not isinstance(integrations, list):
        integrations = []

    integration = None
    for row in integrations:
        if isinstance(row, dict) and row.get("integration_id") == integration_id:
            integration = row
            break

    if integration is None:
        e = _err("NOT_FOUND", "Integration not found", integration_id=integration_id)
        _append_audit("config_send_notification", "error", details=e)
        return e

    if integration.get("enabled") is not True:
        e = _err("INVALID_TRANSITION", "Integration is disabled", integration_id=integration_id)
        _append_audit("config_send_notification", "error", details=e)
        return e

    webhook = integration.get("webhook")
    if not isinstance(webhook, str) or not webhook.strip():
        e = _err("CONFLICT", "Integration lacks required webhook configuration", integration_id=integration_id)
        _append_audit("config_send_notification", "error", details=e)
        return e

    # Persist notification "delivery attempt" as a row in notifications.json
    notifications = _load("notifications.json")
    if not isinstance(notifications, list):
        notifications = []

    now = datetime.datetime.utcnow().isoformat() + "Z"
    notification_id = "notif_" + uuid.uuid4().hex
    # Schema doesn't include message/timestamps, but we keep them for observability without breaking reads.
    notif_row = {
        "notification_id": notification_id,
        "integration_id": integration_id,
        "channel": integration.get("type", "unknown"),
        "level": level,
        "message": message,
        "sent_at": now,
        "delivery": {
            "status": "sent",
            "target": webhook.strip(),
        },
    }
    notifications.append(notif_row)
    try:
        _save("notifications.json", notifications)
    except Exception as ex:
        e = _err("CONFLICT", "Failed to persist notification", reason=str(ex))
        _append_audit("config_send_notification", "error", details=e)
        return e

    resp = {
        "delivery": {
            "status": "sent",
            "notification_id": notification_id,
            "integration_id": integration_id,
            "level": level,
            "sent_at": now,
        }
    }
    _append_audit("config_send_notification", "ok", details={"integration_id": integration_id, "notification_id": notification_id, "level": level})
    return resp
